package com.example.documentassistant.corpus;

import java.io.IOException;
import java.nio.file.Path;
import java.util.List;

/** Private object storage. Keys are generated by the application, never by clients. */
interface CorpusObjectStore {
  boolean exists(String key) throws IOException;
  void download(String key, Path destination) throws IOException;
  void upload(String key, Path source) throws IOException;
  List<String> list(String prefix) throws IOException;
  void delete(String key) throws IOException;
}
